package keycustody

import (
	"fmt"
	"io"

	"github.com/retnd/retnd/core/internal/copycrypt"
)

// Format is the one seam between key custody and the cryptography ADR 0027
// chooses. It is the smallest thing custody needs. Since EPIC T (ADR 0033)
// every suite in copycrypt's registry is a Format, which the assertion
// below holds at compile time, and AgeFormat (age.go) is the age/v1 suite
// by alias: a managed key is generated by the library, not by this
// package, and nothing here designs a primitive.
//
// What is NOT here, on purpose: a Seal. This package never encrypts
// anything, so an interface that handed it a way to would be an invitation
// to a second write path beside #991's transform. A copycrypt.Suite does
// carry a Seal; custody is handed suites but only ever calls the methods
// below, so the rule holds by what custody calls.
type Format interface {
	// ID names the format a copy, and a bundle, was written under. It is a
	// stable string recorded per copy and per key, never a knob an operator
	// sets. It equals the per-copy format id migration 0015 stores and the
	// suite id migration 0020 stores per key.
	ID() string

	// Generate mints a fresh key from a CSPRNG. secret is what the key
	// file holds (for age, the one-line identity), recipient is the public
	// half, which is not secret and is the only key-related string that
	// may reach a surface.
	Generate() (secret []byte, recipient string, err error)

	// Recipient derives the public half from secret, or refuses a secret
	// that is not a key of this format. It is how an external key is
	// checked for shape and how a managed key file is checked against its
	// record, without the material leaving the call.
	Recipient(secret []byte) (string, error)

	// Open returns a reader of the plaintext behind ciphertext under
	// secret. It must return an error, and no reader, for a header it
	// cannot authenticate, and a streaming implementation must not yield a
	// byte it has not authenticated. Bundle.Decrypt relies on that and does
	// not buffer.
	Open(secret []byte, ciphertext io.Reader) (io.Reader, error)
}

// Every copycrypt suite is a Format (EPIC T, ADR 0033 D5). This is why
// copycrypt declares Format's methods instead of embedding this interface:
// the assignment is checked here, in the package that owns the seam.
var _ Format = copycrypt.Suite(nil)

// formatOf is the Format a key of suiteID is read and checked under. An
// empty id is a key written before migration 0020, which is age/v1 by
// construction. The store's own format answers for its own id, so a store
// opened with a format keeps using that exact value.
func (s *Store) formatOf(suiteID string) (Format, error) {
	if suiteID == "" {
		suiteID = copycrypt.AgeX25519ID
	}
	if s.format != nil && s.format.ID() == suiteID {
		return s.format, nil
	}
	if suite, ok := copycrypt.Lookup(suiteID); ok {
		return suite, nil
	}
	return nil, fmt.Errorf("%w: %q", ErrUnknownSuite, suiteID)
}

// ErrUnknownSuite is the refusal for a key, a bundle or a request naming a
// suite this build has no adapter for. It is copycrypt's value.
var ErrUnknownSuite = copycrypt.ErrUnknownSuite
